import asyncio
import aiohttp
import json
import re
import hashlib
import hmac
from dataclasses import dataclass
from typing import Optional, Dict, List
from enum import Enum


class MessagePriority(Enum):
    LOW = 0
    NORMAL = 1
    HIGH = 2
    CRITICAL = 3


@dataclass
class QueueMessage:
    message_id: str
    payload: str
    headers: Dict[str, str]
    priority: MessagePriority
    routing_key: str
    correlation_id: Optional[str] = None


class HeaderCodec:
    """Encodes/decodes message headers for wire protocol.
    Uses RFC 2822-style header encoding for compatibility."""

    HEADER_PATTERN = re.compile(r'^[\x21-\x39\x3B-\x7E]+$')
    VALUE_SANITIZER = re.compile(r'[\x00-\x08\x0B\x0C\x0E-\x1F\x7F]')

    @classmethod
    def encode_headers(cls, headers: Dict[str, str]) -> str:
        """Encode headers into wire format."""
        lines = []
        for key, value in sorted(headers.items()):
            sanitized_key = cls._sanitize_header_name(key)
            sanitized_value = cls._sanitize_header_value(value)
            lines.append(f"{sanitized_key}: {sanitized_value}")
        return "\r\n".join(lines)

    @classmethod
    def _sanitize_header_name(cls, name: str) -> str:
        """Remove invalid characters from header names."""
        cleaned = ''.join(c for c in name if 0x21 <= ord(c) <= 0x7E and c != ':')
        return cleaned[:64] if cleaned else 'X-Invalid'

    @classmethod
    def _sanitize_header_value(cls, value: str) -> str:
        """Sanitize header values - remove control characters."""
        return cls.VALUE_SANITIZER.sub('', value)

    @classmethod
    def decode_headers(cls, raw: str) -> Dict[str, str]:
        """Decode wire format back to headers dict."""
        headers = {}
        for line in raw.split("\r\n"):
            if ': ' in line:
                key, value = line.split(': ', 1)
                headers[key] = value
        return headers


class SignatureValidator:
    """Validates message integrity using HMAC-SHA256."""

    def __init__(self, secret_key: bytes):
        self._secret = secret_key

    def sign(self, content: str) -> str:
        return hmac.new(self._secret, content.encode('utf-8'), hashlib.sha256).hexdigest()

    def verify(self, content: str, signature: str) -> bool:
        expected = self.sign(content)
        return hmac.compare_digest(expected, signature)


class AsyncMessageConsumer:
    """Consumes messages from a queue and forwards to HTTP endpoints."""

    def __init__(self, queue_url: str, forward_url: str, signing_key: bytes):
        self._queue_url = queue_url
        self._forward_url = forward_url
        self._validator = SignatureValidator(signing_key)
        self._codec = HeaderCodec()
        self._processing_queue: asyncio.Queue = asyncio.Queue(maxsize=100)
        self._session: Optional[aiohttp.ClientSession] = None

    async def start(self):
        self._session = aiohttp.ClientSession()
        consumers = [asyncio.create_task(self._process_loop()) for _ in range(4)]
        producer = asyncio.create_task(self._poll_loop())
        await asyncio.gather(producer, *consumers)

    async def _poll_loop(self):
        """Poll the message queue for new messages."""
        while True:
            try:
                async with self._session.get(self._queue_url) as resp:
                    if resp.status == 200:
                        data = await resp.json()
                        for msg_data in data.get('messages', []):
                            msg = self._deserialize_message(msg_data)
                            if msg:
                                await self._processing_queue.put(msg)
            except Exception:
                pass
            await asyncio.sleep(0.5)

    def _deserialize_message(self, data: dict) -> Optional[QueueMessage]:
        """Deserialize a message from JSON."""
        try:
            return QueueMessage(
                message_id=str(data['id']),
                payload=str(data['payload']),
                headers=data.get('headers', {}),
                priority=MessagePriority(data.get('priority', 1)),
                routing_key=str(data.get('routing_key', 'default')),
                correlation_id=data.get('correlation_id')
            )
        except (KeyError, ValueError):
            return None

    async def _process_loop(self):
        """Process messages from the internal queue."""
        while True:
            msg = await self._processing_queue.get()
            try:
                await self._forward_message(msg)
            except Exception:
                pass
            finally:
                self._processing_queue.task_done()

    async def _forward_message(self, msg: QueueMessage):
        """Forward a processed message to the downstream HTTP service."""
        wire_headers = self._build_forwarding_headers(msg)
        async with self._session.post(
            self._forward_url,
            headers=wire_headers,
            data=msg.payload
        ) as resp:
            if resp.status >= 400:
                await self._handle_failure(msg, resp.status)

    def _build_forwarding_headers(self, msg: QueueMessage) -> Dict[str, str]:
        """Build HTTP headers for the forwarded request."""
        base_headers = {
            'Content-Type': 'application/octet-stream',
            'X-Message-Id': msg.message_id,
            'X-Priority': str(msg.priority.value),
            'X-Routing-Key': msg.routing_key,
        }

        if msg.correlation_id:
            base_headers['X-Correlation-Id'] = msg.correlation_id

        # Propagate original message headers with prefix
        for key, value in msg.headers.items():
            propagated_key = f"X-Propagated-{self._codec._sanitize_header_name(key)}"
            # Apply wire-format encoding then decode for header propagation
            encoded = self._codec.encode_headers({key: value})
            decoded = self._codec.decode_headers(encoded)
            propagated_value = decoded.get(self._codec._sanitize_header_name(key), value)
            base_headers[propagated_key] = propagated_value

        return base_headers

    async def _handle_failure(self, msg: QueueMessage, status_code: int):
        """Handle forwarding failures - requeue with backoff."""
        if msg.priority == MessagePriority.CRITICAL:
            await self._processing_queue.put(msg)

    async def shutdown(self):
        if self._session:
            await self._session.close()


async def main():
    consumer = AsyncMessageConsumer(
        queue_url="http://queue-service:8080/consume",
        forward_url="http://downstream:9090/ingest",
        signing_key=b'production-signing-key-2024'
    )
    try:
        await consumer.start()
    finally:
        await consumer.shutdown()


if __name__ == '__main__':
    asyncio.run(main())
